    "搭配 LongCat DMD 蒸餾 LoRA 建議 12 步，步數越高單影格肌膚與口型細節越豐富。",
    "配合 LongCat DMD 蒸餾 LoRA 推薦 12 步，步數越高單幀皮膚與口型細節越豐富。",
    "LongCat DMD 蒸留 LoRA との併用時は 12 ステップ推奨。ステップ数を増やすほど肌や口元の細部が精細になります。",
    "LongCat DMD 증류 LoRA와 함께 12스텝을 권장하며, 스텝이 높을수록 단일 프레임 피부 및 입모양 디테일이 풍부해집니다.",
