    "上传 5～15 秒清晰人声即可克隆该音色（优先级高于内置女声）；留空则自动使用上方所选内置女声（IndexTTS-2 仅在选用「自定义音色」时必须上传）。",
    "Upload 5-15 s of clear speech to clone that voice (takes priority over the built-in female voice); leave blank to use the selected built-in female voice above (required for IndexTTS-2 only when Custom Voice is selected).",
    "上傳 5～15 秒清晰人聲即可複製該音色（優先順序高於內建女聲）；留空則自動使用上方所選內建女聲（IndexTTS-2 僅在選用「自訂音色」時必須上傳）。",
