    "5〜15 秒のクリアな人声をアップロードするとその声質をクローンできます（組み込み女性ボイスより優先）。空欄の場合は上で選択した組み込み女性ボイスを自動使用します（IndexTTS-2 は「カスタム音声」選択時のみ必須）。",
    "5-15초의 깨끗한 사람 음성을 업로드하면 해당 음색을 클로닝합니다(기본 제공 여성 음색보다 우선 적용). 비워 두면 위에서 선택한 기본 제공 여성 음색이 자동 사용됩니다(IndexTTS-2는 '사용자 지정 음색' 선택 시에만 필수 업로드).",
