    "8 steps is officially recommended with the LongCat-Avatar 1.5 DMD distillation LoRA for both rapid sampling and crisp lip-sync detail (fine-tune between 6 and 12 steps as needed).",
    "搭配 LongCat-Avatar 1.5 DMD 蒸餾 LoRA 官方建議 8 步，兼顧極速取樣與精準口型細節（可依需求在 6～12 步微調）。",
