    "LongCat-Avatar 1.5 DMD 蒸留 LoRA との併用時は公式推奨の 8 ステップで、高速サンプリングと高精度なリップシンク細部を両立します（必要に応じて 6〜12 ステップで微調整可能）。",
    "LongCat-Avatar 1.5 DMD 증류 LoRA와 함께 공식 권장 8스텝을 사용하면 초고속 샘플링과 정밀한 립싱크 디테일을 모두 확보할 수 있습니다(필요에 따라 6-12스텝 범위에서 미세 조정 가능).",
