    "Bilibili IndexTeam 오픈소스 2.5세대 산업용 제로샷 클로닝 엔진으로, 2.0 대비 2.28배 빨라졌으며 GRPO 발음 강화, 독립 감정 오디오 전이, 네이티브 속도 조절 및 <한자|PINYIN> 정밀 발음 교정을 지원합니다. 비상업적 연구 전용입니다.",
